{
    complete_rows <- function(...) {
        m <- do.call(cbind, list(...))
        m[stats::complete.cases(m), , drop = FALSE]
    }
    friedman <- function(m, comps = "all", control = 1, corrected = TRUE) {
        n <- nrow(m)
        k <- ncol(m)
        ft <- friedman.test(m)
        r <- t(apply(m, 1, rank))
        rank_sum <- colSums(r)
        mean_rank <- rank_sum/n
        out <- list(k = k, n = n, statistic = unname(ft$statistic), df = unname(ft$parameter), 
            p = ft$p.value, groups = lapply(seq_len(k), function(j) list(rank_sum = rank_sum[j], 
                mean_rank = mean_rank[j])))
        out$comparisons <- if (comps == "none") 
            list()
        else {
            pairs <- unname(if (comps == "all") {
                do.call(rbind, lapply(seq_len(k - 1), function(i) cbind(i, (i + 1):k)))
            }
            else {
                cbind(control, seq_len(k)[-control])
            })
            K <- nrow(pairs)
            se <- sqrt(k * (k + 1)/(6 * n))
            lapply(seq_len(K), function(x) {
                i <- pairs[x, 1]
                j <- pairs[x, 2]
                d <- mean_rank[i] - mean_rank[j]
                z <- abs(d)/se
                p <- 2 * pnorm(z, lower.tail = FALSE)
                list(i = i, j = j, diff = d, z = z, p_unadjusted = p, p = if (corrected) min(1, 
                  K * p) else p)
            })
        }
        out
    }
}
